--
-- wordpress-routines-install.sql: the synthetic routine set of the wordpress sample.
-- Generated by scripts/render_sample_routines.py from wordpress-routines.json.
-- Do not edit by hand: change the JSON set and render again.
-- Run it on the sample's MySQL source, in the `wordpress` database.
--
-- Run it with the mysql client as the master user `admin`, which every routine but
-- one names as its DEFINER. wp_refresh_comment_count names `wp_user`@`localhost`,
-- so the run shows its DEFINER rewrite; creating it needs the SET_USER_ID privilege.
-- Once installed, the trigger adds 1 to a post's comment_count on each new comment,
-- and the event, with the event scheduler on, deletes Action Scheduler log rows
-- older than 30 days once a day. Remove them with the remove script.
-- Each object is dropped first, so the script can run again.

DELIMITER $$

-- function wp_post_comment_count
SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_520_ci'$$
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION'$$
DROP FUNCTION IF EXISTS `wp_post_comment_count`$$
CREATE DEFINER=`admin`@`%` FUNCTION `wp_post_comment_count`(`p_post_id` bigint unsigned) RETURNS int
    READS SQL DATA
BEGIN
  DECLARE n INT DEFAULT 0;
  SELECT COUNT(*) INTO n FROM wp_comments WHERE comment_post_ID = p_post_id;
  RETURN n;
END$$

-- procedure wp_bulk_import_mode
SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_520_ci'$$
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION'$$
DROP PROCEDURE IF EXISTS `wp_bulk_import_mode`$$
CREATE DEFINER=`admin`@`%` PROCEDURE `wp_bulk_import_mode`(IN `p_on` tinyint)
BEGIN
  IF p_on = 1 THEN
    SET GLOBAL innodb_flush_log_at_trx_commit = 2;
  ELSE
    SET GLOBAL innodb_flush_log_at_trx_commit = 1;
  END IF;
END$$

-- procedure wp_refresh_comment_count
SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_520_ci'$$
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION'$$
DROP PROCEDURE IF EXISTS `wp_refresh_comment_count`$$
CREATE DEFINER=`wp_user`@`localhost` PROCEDURE `wp_refresh_comment_count`(IN `p_post_id` bigint unsigned)
    MODIFIES SQL DATA
BEGIN
  UPDATE wp_posts SET comment_count = wp_post_comment_count(p_post_id)
   WHERE ID = p_post_id;
END$$

-- trigger wp_comments_count_after_insert
SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_520_ci'$$
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION'$$
DROP TRIGGER IF EXISTS `wp_comments_count_after_insert`$$
CREATE DEFINER=`admin`@`%` TRIGGER `wp_comments_count_after_insert` AFTER INSERT ON `wp_comments` FOR EACH ROW UPDATE wp_posts SET comment_count = comment_count + 1
 WHERE ID = NEW.comment_post_ID$$

-- event wp_purge_action_logs
SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_520_ci'$$
SET SESSION time_zone = 'SYSTEM'$$
SET SESSION sql_mode = 'STRICT_TRANS_TABLES,NO_ENGINE_SUBSTITUTION'$$
DROP EVENT IF EXISTS `wp_purge_action_logs`$$
CREATE DEFINER=`admin`@`%` EVENT `wp_purge_action_logs` ON SCHEDULE EVERY 1 DAY STARTS '2026-04-01 03:00:00' ON COMPLETION NOT PRESERVE ENABLE DO DELETE FROM wp_actionscheduler_logs
 WHERE log_date_gmt < UTC_TIMESTAMP() - INTERVAL 30 DAY$$

DELIMITER ;
